import { AE_MODES } from "./config/ffg-active-effect-modes.js";
/**
 * A systems implementation of the Star Wars RPG by Fantasy Flight Games.
 * Author: Esrin
 * Software License: GNU GPLv3
 */

// Import Modules
import { FFG } from "./swffg-config.js";
import { ActorFFG } from "./actors/actor-ffg.js";
import { TokenFFG } from "./tokens/token-ffg.js";
import CombatantFFG, {
  CombatFFG,
  CombatTrackerFFG,
  registerHandleCombatantRemoval,
  updateCombatTracker
} from "./combat-ffg.js";
import { ActiveEffectFFG} from "./active-effects/active-effect-ffg.js";
import { ItemFFG } from "./items/item-ffg.js";
import { ItemSheetFFG } from "./items/item-sheet-ffg.js";
import { ItemSheetFFGV2 } from "./items/item-sheet-ffg-v2.js";
import { CodexItemSheet } from "./items/codex-item-sheet.js";
import { ActorSheetFFG } from "./actors/actor-sheet-ffg.js";
import { ActorSheetFFGV2 } from "./actors/actor-sheet-ffg-v2.js";
import { AdversarySheetFFG } from "./actors/adversary-sheet-ffg.js";
import { AdversarySheetFFGV2 } from "./actors/adversary-sheet-ffg-v2.js";
import { CodexActorSheet, CodexAdversarySheet } from "./actors/codex-sheets.js";
import { DicePoolFFG, RollFFG } from "./dice-pool-ffg.js";
import { GroupManager } from "./groupmanager-ffg.js";
import PopoutEditor from "./popout-editor.js";

import DiceHelpers from "./helpers/dice-helpers.js";
import Helpers from "./helpers/common.js";
import TemplateHelpers from "./helpers/partial-templates.js";
import SkillListImporter from "./importer/skills-list-importer.js";
import DestinyTracker from "./ffg-destiny-tracker.js";
import { defaultSkillList } from "./config/ffg-skillslist.js";
import { skillModifierTypes } from "./config/ffg-modifiers.js";
import SettingsHelpers from "./settings/settings-helpers.js";
import {register_crew} from "./helpers/crew.js";

// Import Dice Types
import { AbilityDie, BoostDie, ChallengeDie, DifficultyDie, ForceDie, ProficiencyDie, SetbackDie } from "./dice-pool-ffg.js";
import { createFFGMacro, updateMacro } from "./helpers/macros.js";
import EmbeddedItemHelpers from "./helpers/embeddeditem-helpers.js";
import { ApplyDamage } from "./helpers/apply-damage.js";
import { ApplyCrit } from "./helpers/apply-crit.js";
import { ReplaceDie } from "./helpers/replace-die.js";
import { registerGMBridge } from "./helpers/gm-bridge.js";
import DataImporter from "./importer/data-importer.js";
import FlagMigrationHelpers from "./helpers/flag-migration-helpers.js";
import RollBuilderFFG from "./dice/roll-builder.js";
import CrewSettings from "./settings/crew-settings.js";
import {register_dice_enricher, register_oggdude_tag_enricher, register_roll_tag_enricher} from "./helpers/journal.js";
import {drawAdversaryCount, drawMinionCount, registerTokenControls} from "./helpers/token.js";
import {handleUpdate} from "./swffg-migration.js";
import SWAImporter from "./importer/swa-importer.js";
import {CharacterCreator} from "./helpers/character-creator.js";
import {xpLogUndo} from "./helpers/actor-helpers.js";
import {register_system_tours} from "./helpers/tours.js";
import {registerSystemDataModels, reportDataModelConformance} from "./data/index.js";
import { computeCritAvailability } from "./helpers/crit-availability.js";

/* -------------------------------------------- */
/*  Foundry VTT Initialization                  */
/* -------------------------------------------- */

async function parseSkillList() {
  try {
    return JSON.parse(await game.settings.get("starwarsffg", "arraySkillList"));
  } catch (e) {
    CONFIG.logger.log("Could not parse custom skill list, returning raw setting");
    return await game.settings.get("starwarsffg", "arraySkillList");
  }
}

function registerActorItemValidationHooks() {
  Hooks.on("preCreateItem", (item) => {
    if (!item?.isEmbedded || item.parent?.documentName !== "Actor") return;

    const actor = item.actor ?? item.parent;
    if (!actor) return;

    // Only allow one species and one career on actor types that use them.
    if (item.type === "species" || item.type === "career") {
      if (["character", "nemesis", "rival"].includes(actor.type)) {
        const itemToDelete = actor.items.filter((i) => (i.type === item.type) && (i.id !== item.id));
        itemToDelete.forEach((i) => {
          actor.items.get(i.id)?.delete();
        });
      } else if (actor.type === "minion") {
        ui.notifications.warn(`Item type '${item.type}' cannot be added to 'minion' actor types.`);
        return false;
      }
    }

    // Critical Damage can only be added to vehicles and Critical Injury can only
    // be added to character-like actors.
    if (item.type === "criticaldamage" && actor.type !== "vehicle") {
      ui.notifications.warn("Critical Damage can only be added to 'vehicle' actor types.");
      return false;
    }
    if (item.type === "criticalinjury" && !["character", "nemesis", "rival"].includes(actor.type)) {
      ui.notifications.warn("Critical Injuries can only be added to 'character' actor types.");
      return false;
    }

    // Prevent adding character data type items to vehicles.
    if (["career", "forcepower", "talent", "signatureability", "specialization", "species", "ability"].includes(item.type.toString()) && actor.type === "vehicle") {
      ui.notifications.warn(`Item type '${item.type}' cannot be added to 'vehicle' actor types.`);
      return false;
    }

    // Crit-Trauma counter: stamp the day a character crit was received so Resilience
    // self-heal is gated for a week. Stamp-iff-null — a copied crit with an existing
    // receivedDay keeps its timeline. criticaldamage (vehicles) is NOT stamped.
    if (item.type === "criticalinjury" && item.parent?.documentName === "Actor" && (item.system?.receivedDay === null || item.system?.receivedDay === undefined)) {
      const day = Math.floor(Number(game.settings.get("starwarsffg", "campaignDay")) || 0);
      item.updateSource({ "system.receivedDay": day });
    }
  });
}

Hooks.on("setup", function (){
  // add dice symbol rendering to the text editor for journal pages
  register_roll_tag_enricher();
  register_oggdude_tag_enricher();
  register_dice_enricher();
  register_system_tours();
});

// Merge the Codex localization file into the translation table. Codex labels are
// kept in their own lang/codex/<lang>.json (separate from the base system strings)
// and loaded here in code rather than via a second manifest language entry, so
// they resolve on a simple client reload instead of only after a full world
// relaunch (system.json is re-read only on relaunch). i18nInit fires right after
// the base table loads. English is merged first as a fallback base, then the
// active language on top when it differs.
Hooks.on("i18nInit", async function () {
  const langs = game.i18n.lang && game.i18n.lang !== "en" ? ["en", game.i18n.lang] : ["en"];
  for (const lang of langs) {
    try {
      const json = await foundry.utils.fetchJsonWithTimeout(`systems/starwarsffg/lang/codex/${lang}.json`);
      foundry.utils.mergeObject(game.i18n.translations, foundry.utils.expandObject(json));
    } catch (e) {
      // No codex file for this language (e.g. only English exists) — skip quietly.
    }
  }
});

// Apply optional label overrides for Credits, Obligation, Morality, Duty, and
// Conflict. i18nInit fires immediately after the translation table is loaded and
// is the canonical place to mutate it, so overriding the translation entry here
// updates every template and code path that localizes these keys. Settings are
// registered in the init hook, which runs before i18nInit.
Hooks.on("i18nInit", function () {
  const labelOverrides = {
    labelCredits: "SWFFG.DescriptionCredits",
    labelObligation: "SWFFG.DescriptionObligation",
    labelMorality: "SWFFG.DescriptionMorality",
    labelDuty: "SWFFG.DescriptionDuty",
    labelConflict: "SWFFG.DescriptionConflict",
  };
  for (const [settingKey, translationKey] of Object.entries(labelOverrides)) {
    try {
      const override = game.settings.get("starwarsffg", settingKey);
      if (override) {
        foundry.utils.setProperty(game.i18n.translations, translationKey, override);
      }
    } catch (e) {
      // Setting not registered yet (unexpected hook ordering) — skip rather than
      // abort system startup. The codex sheet reads these settings directly, so
      // its labels update regardless.
    }
  }
});

Hooks.once("init", async function () {
  console.log(`Initializing SWFFG System`);
  // Place our classes in their own namespace for later reference.
  game.ffg = {
    ActorFFG,
    TokenFFG,
    ItemFFG,
    CombatFFG,
    CombatantFFG,
    CombatTrackerFFG,
    RollFFG,
    DiceHelpers,
    RollBuilderFFG,
    addons: {
      PopoutEditor,
    },
    diceterms: [AbilityDie, BoostDie, ChallengeDie, DifficultyDie, ForceDie, ProficiencyDie, SetbackDie],
    ActiveEffectFFG,
    // Read-only migration self-check: await game.ffg.reportDataModelConformance()
    reportDataModelConformance,
  };

  // Define custom log prefix and logger
  CONFIG.module = "Starwars FFG";
  CONFIG.logger = Helpers.logger;
  registerActorItemValidationHooks();

  // Define custom Entity classes. This will override the default Actor
  // to instead use our extended version.
  CONFIG.Actor.documentClass = ActorFFG;
  CONFIG.Item.documentClass = ItemFFG;
  CONFIG.ActiveEffect.documentClass = ActiveEffectFFG;

  // System Data Models — template.json → DataModel migration (Stage 0: no-op).
  // Registers per-sub-type schemas into CONFIG.*.dataModels as stages land;
  // until then template.json remains the sole schema source.
  registerSystemDataModels();

  // we do not want the legacy active effect transfer mode
  // also, reeeeeeeeeeeeeeeee
  CONFIG.ActiveEffect.legacyTransferral = false;

  // Define custom Roll class
  CONFIG.Dice.rolls.push(CONFIG.Dice.rolls[0]);
  CONFIG.Dice.rolls[0] = RollFFG;

  // Define DiceTerms
  CONFIG.Dice.terms["a"] = AbilityDie;
  CONFIG.Dice.terms["b"] = BoostDie;
  CONFIG.Dice.terms["c"] = ChallengeDie;
  CONFIG.Dice.terms["i"] = DifficultyDie;
  CONFIG.Dice.terms["f"] = ForceDie;
  CONFIG.Dice.terms["p"] = ProficiencyDie;
  CONFIG.Dice.terms["s"] = SetbackDie;

  // Give global access to FFG config.
  CONFIG.FFG = FFG;

  // TURN ON OR OFF HOOK DEBUGGING
  CONFIG.debug.hooks = false;

  // Enable debug messages in console
  game.settings.register("starwarsffg", "enableDebug", {
    name: game.i18n.localize("SWFFG.EnableDebug"),
    hint: game.i18n.localize("SWFFG.EnableDebugHint"),
    scope: "world",
    config: true,
    default: false,
    type: Boolean,
    onChange: this.debouncedReload,
  });

   /**
   * Register statuses to add
   */
  game.settings.register("starwarsffg", "additionalStatuses", {
    name: game.i18n.localize("SWFFG.Settings.AdditionalStatuses.Name"),
    hint: game.i18n.localize("SWFFG.Settings.AdditionalStatuses.Hint"),
    scope: "world",
    config: false,
    default: "[]",
    type: String,
    onChange: (rule) => window.location.reload()
  });

  // register turn marker reconfigurator
  game.settings.register("starwarsffg", "configuredTurnMarker", {
    name: "configuredTurnMarker",
    hint: "configuredTurnMarker",
    scope: "world",
    config: false,
    default: false,
    type: Boolean,
  });

  // Override the default Token _drawBar function to allow for FFG style wound and strain values.
  foundry.canvas.placeables.Token.prototype._drawBar = function (number, bar, data) {
    let val = Number(data.value);
    // FFG style behaviour for wounds and strain.
    let aboveThreshold = 0;
    if (data.attribute === "stats.wounds" || data.attribute === "stats.strain" || data.attribute === "stats.hullTrauma" || data.attribute === "stats.systemStrain") {
      val = Number(data.max - data.value);
      aboveThreshold = Math.max(data.value - data.max, 0);
    }

    // draw the empty bar
    let h = Math.max(canvas.dimensions.size / 12, 8);
    bar.clear()
      .beginFill(0x000000, 0.5)
      .lineStyle(2, 0x000000, 0.9)
      .drawRoundedRect(0, 0, this.w, h, 3);
    let startX = 1;
    let startY = 1;

    const colors = {
      "stats.wounds": {
        ok: game.settings.get("starwarsffg", "ui-token-healthy"),
        damaged: game.settings.get("starwarsffg", "ui-token-wounded"),
        overDamaged: game.settings.get("starwarsffg", "ui-token-overwounded"),
      },
      "stats.hullTrauma": {
        ok: game.settings.get("starwarsffg", "ui-token-healthy"),
        damaged: game.settings.get("starwarsffg", "ui-token-wounded"),
        overDamaged: game.settings.get("starwarsffg", "ui-token-overwounded"),
      },
      "stats.strain": {
        ok: game.settings.get("starwarsffg", "ui-token-stamina-ok"),
        damaged: game.settings.get("starwarsffg", "ui-token-stamina-damaged"),
        overDamaged: game.settings.get("starwarsffg", "ui-token-stamina-over"),
      },
      "stats.systemStrain": {
        ok: game.settings.get("starwarsffg", "ui-token-stamina-ok"),
        damaged: game.settings.get("starwarsffg", "ui-token-stamina-damaged"),
        overDamaged: game.settings.get("starwarsffg", "ui-token-stamina-over"),
      },
    }

    if (["stats.wounds", "stats.hullTrauma", "stats.strain", "stats.systemStrain"].includes(data.attribute)) {
      if (aboveThreshold > 0) {
        // render the above-threshold portion of the bar
        let abovePct = Math.min(aboveThreshold / data.max, 1);
        bar
        .beginFill(colors[data.attribute]["overDamaged"], 0.8)
        .lineStyle(1, 0x000000, 0.8)
        .drawRoundedRect(startX, startY, abovePct * (this.w - 2), h - 2, 2);
        // render the rest as wounds
        startX = abovePct * (this.w - 2) + 1;
        let remainingLength = this.w  - abovePct * (this.w - 2) - 2;
        bar
        .beginFill(colors[data.attribute]["damaged"], 0.8)
        .lineStyle(1, 0x000000, 0.8)
        .drawRoundedRect(startX, startY, remainingLength, h - 2, 2);
      } else {
        // render healthy and then unhealthy portions of the bar
        let woundedPct = Math.min((data.max - data.value) / data.max, 1);
        bar
        .beginFill(colors[data.attribute]["ok"], 0.8)
        .lineStyle(1, 0x000000, 0.8)
        .drawRoundedRect(startX, startY, woundedPct * (this.w - 2), h - 2, 2);
        // remaining health
        startX = woundedPct * (this.w - 2) + 1;
        let remainingLength = this.w - woundedPct * (this.w - 2) - 2;
        bar
        .beginFill(colors[data.attribute]["damaged"], 0.8)
        .lineStyle(1, 0x000000, 0.8)
        .drawRoundedRect(startX, startY, remainingLength, h - 2, 2);
      }
    } else {
      // render normally
      const pct = Math.clamp(val, 0, data.max) / data.max;
      let color = number === 0 ? [1 - pct / 2, pct, 0] : [0.5 * pct, 0.7 * pct, 0.5 + pct / 2];
      bar
      .beginFill(PIXI.utils.rgb2hex(color), 0.8)
      .lineStyle(1, 0x000000, 0.8)
      .drawRoundedRect(1, 1, pct * (this.w - 2), h - 2, 2);
    }

    // Set position
    let posY = number === 0 ? this.h - h : 0;
    bar.position.set(0, posY);
  };

  // Load character templates so that dynamic skills lists work correctly
  await foundry.applications.handlebars.loadTemplates(["systems/starwarsffg/templates/actors/ffg-character-sheet.html", "systems/starwarsffg/templates/actors/ffg-minion-sheet.html", "systems/starwarsffg/templates/actors/codex/codex-character.html", "systems/starwarsffg/templates/actors/codex/codex-minion.html", "systems/starwarsffg/templates/actors/codex/codex-vehicle.html", "systems/starwarsffg/templates/items/codex/codex-item.html", "systems/starwarsffg/templates/items/codex/codex-gear.html", "systems/starwarsffg/templates/items/codex/codex-weapon.html", "systems/starwarsffg/templates/items/codex/codex-armour.html", "systems/starwarsffg/templates/items/codex/codex-talent.html", "systems/starwarsffg/templates/items/codex/codex-crit.html", "systems/starwarsffg/templates/items/codex/codex-shipweapon.html", "systems/starwarsffg/templates/items/codex/codex-itemattachment.html", "systems/starwarsffg/templates/items/codex/codex-shipattachment.html", "systems/starwarsffg/templates/items/codex/codex-forcepower.html", "systems/starwarsffg/templates/items/codex/codex-specialization.html", "systems/starwarsffg/templates/items/codex/codex-signatureability.html"]);

  SettingsHelpers.initLevelSettings();

  const uitheme = game.settings.get("starwarsffg", "ui-uitheme");

  switch (uitheme) {
    case "mandar": {
      $('link[href*="styles/starwarsffg.css"]').prop("disabled", true);
      $("head").append('<link href="systems/starwarsffg/styles/mandar.css" rel="stylesheet" type="text/css" media="all">');
      break;
    }
    case "mandarBeskarAstromech": {
      $('link[href*="styles/starwarsffg.css"]').prop("disabled", true);
      $("head").append('<link href="systems/starwarsffg/styles/mandarBeskarAstromech.css" rel="stylesheet" type="text/css" media="all">');
      break;
    }
    default: {
      $('link[href*="styles/starwarsffg.css"]').prop("disabled", false);
    }
  }

  // CODEX II stylesheet — appended LAST in <head>, after whichever UI theme link
  // was added above. Fully self-contained: everything is scoped under `.cdx` and
  // styles only bespoke `.cdx-*` classes, so it neither depends on nor is
  // overridden by the active theme. (system.json `styles` is unreliable here —
  // the default mandar theme disables system styles at init.)
  // ?v=<timestamp> busts the browser cache so edits to cdx.css load on a plain
  // reload — the <link> was otherwise cached forever by its fixed URL, which is
  // why CSS changes "didn't apply". TODO: switch the buster to the system
  // version (game.system.version) for release so the file caches between bumps.
  $("head").append(`<link href="systems/starwarsffg/styles/cdx.css?v=${Date.now()}" rel="stylesheet" type="text/css" media="all">`);
  // Each Codex scheme's palette (and any scheme-specific rules) lives in its own
  // file, appended AFTER cdx.css so it layers on top of the base Codex styles.
  // Republic loads first and doubles as the default palette (its bare `.cdx form`
  // fallback); every scheme-* rule outranks it by specificity. Same cache-buster
  // rationale as cdx.css above.
  for (const scheme of ["republic", "empire", "dark", "light", "mercenary", "eldritch"]) {
    $("head").append(`<link href="systems/starwarsffg/styles/cdx-${scheme}.css?v=${Date.now()}" rel="stylesheet" type="text/css" media="all">`);
  }

  /**
   * Register default XP spend notification
   */
  game.settings.register("starwarsffg", "notifyOnXpSpend", {
    name: game.i18n.localize("SWFFG.Settings.Purchase.Notify.Name"),
    hint: game.i18n.localize("SWFFG.Settings.Purchase.Notify.Hint"),
    scope: "world",
    config: false,
    default: true,
    type: Boolean,
  });
  game.settings.register("starwarsffg", "defaultObligation", {
    name: game.i18n.localize("SWFFG.Settings.Obligation.Default.Name"),
    hint: game.i18n.localize("SWFFG.Settings.Obligation.Default.Hint"),
    scope: "world",
    config: false,
    default: 20,
    type: Number,
  });
  game.settings.register("starwarsffg", "defaultDuty", {
    name: game.i18n.localize("SWFFG.Settings.Duty.Default.Name"),
    hint: game.i18n.localize("SWFFG.Settings.Duty.Default.Hint"),
    scope: "world",
    config: false,
    default: 20,
    type: Number,
  });
  game.settings.register("starwarsffg", "defaultMorality", {
    name: game.i18n.localize("SWFFG.Settings.Morality.Default.Name"),
    hint: game.i18n.localize("SWFFG.Settings.Morality.Default.Hint"),
    scope: "world",
    config: false,
    default: 50,
    type: Number,
  });
  game.settings.register("starwarsffg", "maxRarity", {
    name: game.i18n.localize("SWFFG.Settings.CharCreator.Items.maxRarity.Name"),
    hint: game.i18n.localize("SWFFG.Settings.CharCreator.Items.maxRarity.Hint"),
    scope: "world",
    config: false,
    default: 6,
    type: Number,
  });
  game.settings.register("starwarsffg", "allowRestricted", {
    name: game.i18n.localize("SWFFG.Settings.CharCreator.Items.allowRestricted.Name"),
    hint: game.i18n.localize("SWFFG.Settings.CharCreator.Items.allowRestricted.Hint"),
    scope: "world",
    config: false,
    default: false,
    type: Boolean,
  });
  game.settings.register("starwarsffg", "defaultCredits", {
    name: game.i18n.localize("SWFFG.Settings.Credits.Default.Name"),
    hint: game.i18n.localize("SWFFG.Settings.Credits.Default.Hint"),
    scope: "world",
    config: false,
    default: 500,
    type: Number,
  });

  /**
   * Optional override text for the Credits, Obligation, Morality, and Duty labels.
   * When left blank the default (localized) label is used. When set, the value
   * overrides the matching SWFFG.Description* translation everywhere it appears.
   */
  const labelOverrides = {
    labelCredits: "SWFFG.DescriptionCredits",
    labelObligation: "SWFFG.DescriptionObligation",
    labelMorality: "SWFFG.DescriptionMorality",
    labelDuty: "SWFFG.DescriptionDuty",
    labelConflict: "SWFFG.DescriptionConflict",
  };
  // Debounced so saving several label overrides at once (the settings form sets
  // them in a loop) only triggers one reload AFTER every value is persisted — an
  // immediate reload on the first change would abort the loop and discard the rest.
  const debouncedLabelReload = foundry.utils.debounce(() => window.location.reload(), 100);
  for (const key of Object.keys(labelOverrides)) {
    game.settings.register("starwarsffg", key, {
      name: game.i18n.localize(`SWFFG.Settings.Label.${key.replace("label", "")}.Name`),
      hint: game.i18n.localize(`SWFFG.Settings.Label.${key.replace("label", "")}.Hint`),
      scope: "world",
      config: false,
      default: "",
      type: String,
      onChange: debouncedLabelReload,
    });
  }

  /**
   * Register the option to use generic slots for combat
   */
  game.settings.register("starwarsffg", "useGenericSlots", {
    name: game.i18n.localize("SWFFG.Settings.UseGenericSlots.Name"),
    hint: game.i18n.localize("SWFFG.Settings.UseGenericSlots.Hint"),
    scope: "world",
    config: false,
    default: true,
    type: Boolean,
    onChange: (rule) => window.location.reload()
  });

  if (game.settings.get("starwarsffg", "useGenericSlots")) {
    CONFIG.ui.combat = CombatTrackerFFG;
    CONFIG.Combat.documentClass = CombatFFG;
    CONFIG.Combatant.documentClass = CombatantFFG;
    // override the token placeable object so we can control turn indicators
    CONFIG.Token.objectClass = TokenFFG;
  }

  // The token HUD status menu runs Object.values(CONFIG.statusEffects) in _getStatusEffectChoices;
  // under V14 that throws if the list holds a duplicate id (see dedupeStatusEffectsById). We keep
  // our own effects unique, but other packages append to the list afterwards -- Condition Lab
  // concatenates our effects back onto itself, re-adding every id -- and its rebuild lands after
  // the initial canvas draw, so the canvasInit dedup can't cover this consumer. hudClass is the
  // supported override point (sibling of objectClass above), so sanitise the list right before
  // the menu reads it. Scoped to this one consumer; we do not touch the global CONFIG setter.
  CONFIG.Token.hudClass = class extends CONFIG.Token.hudClass {
    _getStatusEffectChoices(...args) {
      const current = CONFIG.statusEffects;
      const cleaned = dedupeStatusEffectsById(current);
      if (cleaned.length !== current.length) CONFIG.statusEffects = cleaned;
      return super._getStatusEffectChoices(...args);
    }
  };

  /**
   * Register action to take when a user removes a combatant from combat
   */
  game.settings.register("starwarsffg", "removeCombatantAction", {
    name: game.i18n.localize("SWFFG.Settings.RemoveCombatantAction.Name"),
    hint: game.i18n.localize("SWFFG.Settings.RemoveCombatantAction.Hint"),
    scope: "world",
    config: false,
    default: "combatant_only",
    type: String,
    choices: {
      combatant_only: "Combatant Only",
      last_slot: "Last Slot",
      prompt: "Prompt",
    },
  });

