  foundry.documents.collections.Items.unregisterSheet("core", foundry.appv1.sheets.ItemSheet);
  // V2-full migration (Stage 3.7): ItemSheetFFG and ItemSheetFFGV2 now resolve
  // to the same native sheet. ItemSheetFFG is the real, default class;
  // ItemSheetFFGV2 stays registered (no makeDefault) only as a deprecated alias
  // so worlds with `flags.core.sheetClass === "ffg.ItemSheetFFGV2"` keep
  // resolving. Drop the alias entry in the release after V2-full lands.
  foundry.documents.collections.Items.registerSheet("ffg", ItemSheetFFG, { makeDefault: true, label: "Item Sheet" });
  foundry.documents.collections.Items.registerSheet("ffg", ItemSheetFFGV2, { label: "Item Sheet v2 (deprecated, use Item Sheet)" });
  // Codex II item sheet — opt-in, per item, via the ⚙ Sheet config. Detailed
  // templates: weapon/armour/gear/talent; a generic Codex frame covers the other
  // simple types. Complex tree/config types keep the stock sheet (not listed).
  const CODEX_ITEM_TYPES = ["weapon", "armour", "gear", "talent", "forcepower", "specialization", "signatureability", "shipweapon", "itemattachment", "ability", "criticalinjury", "criticaldamage", "obligation", "motivation", "background", "shipattachment", "homesteadupgrade"];
  foundry.documents.collections.Items.registerSheet("ffg", CodexItemSheet, {
    types: CODEX_ITEM_TYPES,
    label: "Codex II Item Sheet",
  });

  // Stash the Codex sheet classes + the types they cover so the document
  // classes' _getSheetClass() (ActorFFG/ItemFFG) can route to them when the
  // client `defaultSheetTheme` setting selects "codex" — without importing the
  // sheet classes into the document modules (which would form an import cycle).
  CONFIG.FFG.codexSheets = {
    actor: { cls: CodexActorSheet, types: CODEX_ACTOR_TYPES },
    item: { cls: CodexItemSheet, types: CODEX_ITEM_TYPES },
  };

  // Add utilities to the global scope, this can be useful for macro makers
  window.DicePoolFFG = DicePoolFFG;

  // add back in the select helper (under a new name, so we don't get warnings)
  Handlebars.registerHelper({
    selectFfg: function (selected, options) {
      const escapedValue = RegExp.escape(Handlebars.escapeExpression(selected));
      const rgx = new RegExp(' value=[\"\']' + escapedValue + '[\"\']');
      const html = options.fn(this);
      return html.replace(rgx, "$& selected");
    }
  });

  // Register Handlebars utilities
  Handlebars.registerHelper("json", JSON.stringify);

  // Allows {if X = Y} type syntax in html using handlebars
  Handlebars.registerHelper("iff", function (a, operator, b, opts) {
    var bool = false;
    switch (operator) {
      case "==":
        bool = a == b;
        break;
      case ">":
        bool = a > b;
        break;
      case "<":
        bool = a < b;
        break;
      case "!=":
        bool = a != b;
        break;
      case "contains":
        if (a && b) {
          bool = a.includes(b);
        } else {
          bool = false;
        }
        break;
      default:
        throw "Unknown operator " + operator;
    }

    if (bool) {
      return opts.fn(this);
    } else {
      return opts.inverse(this);
    }
  });

  Handlebars.registerHelper("renderMultiple", function (count, obj) {
    let items = [];
    for (let i = 0; i < count; i += 1) {
      items.push(obj);
    }

    return new Handlebars.SafeString(items.join(""));
  });

  Handlebars.registerHelper("critAvailability", function (item) {
    const currentDay = Math.floor(Number(game.settings.get("starwarsffg", "campaignDay")) || 0);
    const vehicleLimit = game.settings.get("starwarsffg", "vehicleCritWeeklyLimit");
    const canSelfHeal = !!(item?.parent?.isOwner || game.user?.isGM);
    return computeCritAvailability(item?.system, currentDay, vehicleLimit, canSelfHeal);
  });

  Handlebars.registerHelper("calculateSpecializationTalentCost", function (idString) {
    const id = parseInt(idString.replace("talent", ""), 10);

    const cost = (Math.trunc(id / 4) + 1) * 5;

    return cost;
  });

  Handlebars.registerHelper("calculateSignatureAbilityCost", function (idString) {
    const id = parseInt(idString.replace("upgrade", ""), 10);

    const cost = (Math.trunc(id / 4) + 2) * 5;

    return cost;
  });

  Handlebars.registerHelper("math", function (lvalue, operator, rvalue, options) {
    lvalue = parseFloat(lvalue);
    rvalue = parseFloat(rvalue);

    return {
      "+": lvalue + rvalue,
      "-": lvalue - rvalue,
      "*": lvalue * rvalue,
      "/": lvalue / rvalue,
      "%": lvalue % rvalue,
    }[operator];
  });

  Handlebars.registerHelper("contains", function (obj1, property, value, opts) {
    let bool = false;
    if (Array.isArray(obj1) || obj1 instanceof Collection) {
      bool = obj1.some((e) => e[property] === value);
    } else if (typeof obj1 === "object") {
      bool = Object.keys(obj1).some(function (k) {
        return obj1[k][property] === value;
      });
    } else if (typeof obj1 === "string") {
      return obj1.includes(property);
    }

    if (bool) {
      return opts.fn(this);
    } else {
      return opts.inverse(this);
    }
  });

  Handlebars.registerHelper("keylen", function (obj) {
    try {
      return Object.keys(obj).length;
    } catch (e) {
      return 0;
    }
  });

  Handlebars.registerHelper("in", function (value, array) {
    if (!Array.isArray(array)) {
      return false;
    }
    return array.indexOf(value) >= 0;
  });

  Handlebars.registerHelper("object", function ({ hash }) {
    return hash;
  });
  Handlebars.registerHelper("array", function () {
    return Array.from(arguments).slice(0, arguments.length - 1);
  });

  Handlebars.registerHelper("defaultImage", function(img) {
    return ["icons/svg/mystery-man.svg", "icons/svg/item-bag.svg"].includes(img);
  });

  Handlebars.registerHelper('each_when', function(list, propName, value, options) {
    let result = '';
    for(let i = 0; i < list.length; ++i)
        if(list[i][propName] == value)
            result += options.fn({item: list[i]});

    return result.length > 0 ? result : options.inverse();
  });


  await TemplateHelpers.preload();
});

/**
 * Return a copy of a status-effect list with duplicate ids removed (first entry per id kept) and
 * id-less entries dropped. V14 backs CONFIG.statusEffects with a Proxy whose `ownKeys` trap emits
 * one key per entry, so a duplicate/missing id makes Object.values() throw ("'ownKeys' on proxy:
 * trap returned duplicate entries") and crash the two consumers that iterate it: the canvas
 * texture load (map view) and the token HUD status menu. We register unique ids ourselves, but
 * other packages (e.g. Condition Lab) reassign the list afterwards and re-add our ids, so we
 * sanitise it at each of those consumers -- the canvasInit hook below and the TokenHUD subclass in
 * init -- rather than redefining the global CONFIG.statusEffects setter. Iterating the input uses
 * the array protocol, not `ownKeys`, so it is safe even while the list holds duplicates.
 */
function dedupeStatusEffectsById(value) {
  const list = Array.isArray(value) ? value : Object.values(value ?? {});
  const seen = new Set();
  const cleaned = [];
  let dropped = 0;
  for (const effect of list) {
    const id = effect?.id;
    if (!id || seen.has(id)) {
      dropped += 1;
      continue;
    }
    seen.add(id);
    cleaned.push(effect);
  }
  if (dropped > 0) {
    CONFIG.logger?.warn?.(`Removed ${dropped} duplicate/invalid status effect(s) to avoid a V14 proxy crash`);
  }
  return cleaned;
}
// Sanitise the list before each canvas draw: canvasInit fires ahead of TextureLoader.loadSceneTextures
// in the same Canvas#draw, so a duplicate id reintroduced since the last draw can't crash the map
// view. Reassigns only when duplicates are actually present, so once the list is clean this is a
// no-op. `.length` reads the array target, not the ownKeys trap.
Hooks.on("canvasInit", () => {
  const current = CONFIG.statusEffects;
  const cleaned = dedupeStatusEffectsById(current);
  if (cleaned.length !== current.length) CONFIG.statusEffects = cleaned;
});

